<?php
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Runtime\Owner;
/** Native SQL + the same study simulation, with a single grouped assessment. */
function pr_exclusion_fixture($jump=false,$discard=false){
 global $studyFixtures,$executions;
 $d=pr_definition(true,'text');$q=$d['elements'][0];$d['elements']=array();$q['id']='QE_SOURCE';$q['response_key']='QE_R_SOURCE';$q['properties']['variable_name']='qe_source';$q['properties']['required']=true;$d['elements'][]=$q;
 foreach(array('A','B','COMMON') as $name){$d['elements'][]=array('id'=>'QE_PB_'.$name,'type'=>'page_break','response_key'=>null,'properties'=>array('label'=>'Salto de página'),'options'=>array(),'children'=>array());$e=$q;$e['id']='QE_'.$name;$e['response_key']='QE_R_'.$name;$e['properties']['variable_name']='qe_'.strtolower($name);if($name==='COMMON')$d['elements'][]=$e;else $d['elements'][]=array('id'=>'QE_GROUP_'.$name,'type'=>'group','response_key'=>null,'properties'=>array('label'=>'Branch '.$name),'options'=>array(),'children'=>array($e));}
 $d['flow']['pages']=array();$d['flow']['allow_back']=true;$d['flow']['allow_discard']=$discard;$d=D::validate($d);$source=pr_new(true,'text',$d);$protocol=pe_definition();$protocol['nodes']=array_values(array_filter($protocol['nodes'],static function($n){return $n['kind']==='BLOCK';}));$protocol['protocol_metadata']['execution_planning']='DEPENDENCY_PLAN_V1';$assessment=null;
 foreach($protocol['nodes'] as &$n)if($n['completion_boundary']==='ASSESSMENT'){$assessment=$n['id'];$n['metadata']['native_version_id']=$source['version_id'];$n['metadata']['native_definition_hash']=$source['definition_hash'];foreach(array('nativeQuestions'=>'native_questions','nativeRandomizations'=>'native_randomizations','nativeGroups'=>'native_groups') as $method=>$key){$r=new ReflectionMethod(EIPSI\StudyEngine\Builder\Service::class,$method);$r->setAccessible(true);$n['metadata'][$key]=$r->invoke(null,$d);}}unset($n);
 $protocol['protocol_metadata']['trajectory_conditions']=array();foreach(array('yes'=>'B','no'=>'A') as $value=>$target)$protocol['protocol_metadata']['trajectory_conditions'][]=array('id'=>'QE_LC_'.$value,'label'=>$value,'source'=>array('assessment_id'=>$assessment,'question_id'=>'QE_SOURCE'),'event'=>'ANSWER','priority'=>1,'reference_scope'=>'TRACK_PAST_V1','action_scope'=>'TRACK_FUTURE_V1','predicate'=>array('op'=>'EQ','reference'=>array('kind'=>'ANSWER','assessment_id'=>$assessment,'question_id'=>'QE_SOURCE'),'value'=>$value),'actions'=>array(array('type'=>'EXCLUDE_ELEMENT','target_id'=>$assessment,'element_id'=>'QE_GROUP_'.$target)));
 if($jump)$protocol['protocol_metadata']['trajectory_conditions'][0]['actions'][]=array('type'=>'GO_QUESTION','target_id'=>$assessment,'question_id'=>'QE_COMMON');
 $json=EIPSI\StudyEngine\Contracts\Canonical::json(array('label'=>'Grouped Native','html'=>''));$protocol['nodes'][]=array('kind'=>'CONTENT','id'=>'QE_CONTENT','version_id'=>$protocol['id'],'parent_id'=>$assessment,'position'=>0,'type'=>'TEXT','content'=>array('content_id'=>'QE_C','version'=>1,'snapshot'=>$json,'sha256'=>hash('sha256',$json)),'durable_reference'=>null);
 $p=pe_publish('simple',false,$protocol);$studyFixtures[]=$protocol['study']['logical_id'];$entry=pe_runtime()->handle($p['public']);$cookie=EIPSI\StudyEngine\Runtime\AnonymousAccess::cookieName($p['public']);$_COOKIE[$cookie]=$entry['token'];
 $binding=array('kind'=>'STUDY_ANONYMOUS','public_id'=>$p['public'],'execution_id'=>$entry['access']['execution_id'],'study_version_id'=>$entry['access']['study_version_id'],'participant_id'=>$entry['access']['id'],'block_execution_id'=>$entry['view']['next_action']['payload']['assessment_execution_id']);$native=new Owner();$assigned=$native->studyAssignment($source['version_id'],$binding);$executions[]=$assigned['execution_id'];$f=$native->view($assigned['execution_id']);$f=$native->command($f['execution_id'],pr_command($f,'open'));return array($native,$f,$cookie,$protocol,$d,$assessment);
}
function pr_exclusion_test($fn,$jump=false,$discard=false){$previous=getenv('EIPSI_STUDY_ENGINE_KEYRING');putenv('EIPSI_STUDY_ENGINE_KEYRING='.json_encode(array('current'=>'HTTP_TEST','keys'=>array('HTTP_TEST'=>bin2hex(str_repeat('k',32))))));$cookie=null;try{$args=pr_exclusion_fixture($jump,$discard);$cookie=$args[2];$fn(...$args);}finally{if($cookie)unset($_COOKIE[$cookie]);$previous===false?putenv('EIPSI_STUDY_ENGINE_KEYRING'):putenv('EIPSI_STUDY_ENGINE_KEYRING='.$previous);}}
pr_test('Conditional groups stay private while pending and cannot receive forged answers',function(){pr_exclusion_test(function($native,$f){$dto=EIPSI\AssessmentEditor\Runtime\EffectiveAssessmentProjection::frame($f);$body=D::json($dto['definition']['elements']);pr_assert(strpos($body,'QE_GROUP_A')===false&&strpos($body,'QE_GROUP_B')===false);pr_assert($f['available_pages']===array(0,3));pr_reject(function()use($native,$f){$native->command($f['execution_id'],pr_command($f,'logic',array('QE_R_A'=>'forged')),true);});});});
pr_test('Native navigation skips excluded pages forward and backward',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'yes');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);pr_assert($f['available_pages']===array(0,1,3));$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);pr_assert($f['page']===1);$a['QE_R_A']='branch';$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);pr_assert($f['page']===3);$f=$native->command($f['execution_id'],pr_command($f,'back',$a),true);pr_assert($f['page']===1);});});
pr_test('Changing a prior answer erases excluded partials and never restores them',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'yes');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);$a['QE_R_A']='old branch';$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);$a['QE_R_COMMON']='shared';$f=$native->command($f['execution_id'],pr_command($f,'partial',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'back',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'back',$a),true);$a['QE_R_SOURCE']='no';$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);pr_assert(!isset($f['session']['answers']['QE_R_A']));pr_assert($f['session']['answers']['QE_R_COMMON']==='shared');$stored=json_decode($native->store->find('executions',$f['execution_id'])['partial_json'],true);pr_assert(!isset($stored['answers']['QE_R_A']));$a=$f['session']['answers'];$a['QE_R_SOURCE']='yes';$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);pr_assert(!isset($f['session']['answers']['QE_R_A']));$f=$native->command($f['execution_id'],pr_command($f,'next',$f['session']['answers']));pr_reject(function()use($native,$f){$native->command($f['execution_id'],pr_command($f,'next',$f['session']['answers']));});});});
pr_test('Final submission and analytical export omit excluded branch answers',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'no');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);pr_assert($f['page']===2);$a['QE_R_B']='included';$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);$a['QE_R_COMMON']='shared';$f=$native->command($f['execution_id'],pr_command($f,'submit',$a),true);pr_assert($f['state']==='COMPLETED');$stored=json_decode($native->store->find('executions',$f['execution_id'])['final_json'],true);pr_assert(!isset($stored['answers']['QE_R_A']));pr_assert(strpos(D::json($native->export($f['execution_id'])),'QE_R_A')===false);});});
pr_test('Study simulation uses the same grouped branch exclusions and page navigation',function(){pr_exclusion_test(function($native,$f,$cookie,$protocol,$d,$assessment){$ctx=array('created_at'=>'2026-10-13T08:00:00Z','timezone'=>'UTC','seed_hex'=>str_repeat('01',32));$commands=array(array('kind'=>'ENTER','data'=>array()));$run=function()use($protocol,$ctx,&$commands,$d,$assessment){return EIPSI\StudyEngine\Builder\Experience::run($protocol,$ctx,$commands,array($assessment=>$d));};$r=$run();pr_assert($r['assessment']['available_pages']===array(0,3));$a=array('QE_R_SOURCE'=>'yes');$commands[]=array('kind'=>'ANSWER','data'=>array('answers'=>$a,'touched'=>array()));$r=$run();pr_assert($r['assessment']['available_pages']===array(0,1,3));$commands[]=array('kind'=>'NEXT','data'=>array('answers'=>$a,'touched'=>array()));$r=$run();pr_assert($r['assessment']['session']['page']===1);$a['QE_R_A']='old';$commands[]=array('kind'=>'NEXT','data'=>array('answers'=>$a,'touched'=>array()));$commands[]=array('kind'=>'BACK','data'=>array('answers'=>$a,'touched'=>array()));$commands[]=array('kind'=>'BACK','data'=>array('answers'=>$a,'touched'=>array()));$a['QE_R_SOURCE']='no';$commands[]=array('kind'=>'ANSWER','data'=>array('answers'=>$a,'touched'=>array()));$r=$run();pr_assert(!isset($r['assessment']['session']['answers']['QE_R_A']));pr_assert($r['assessment']['available_pages']===array(0,2,3));});});
pr_test('Public retry after branch exclusion remains idempotent without restoring deleted answers',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'yes');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'next',$a),true);$a['QE_R_A']='old';$f=$native->command($f['execution_id'],pr_command($f,'partial',$a),true);$f=$native->command($f['execution_id'],pr_command($f,'back',$a),true);$a['QE_R_SOURCE']='no';$command=pr_command($f,'logic',$a);$next=$native->command($f['execution_id'],$command,true);$again=$native->command($f['execution_id'],$command,true);pr_assert($again['revision']===$next['revision']);pr_assert(!isset($again['session']['answers']['QE_R_A']));});});
pr_test('Question jump and conditional exclusion retain both bindings in one transition',function(){pr_exclusion_test(function($native,$f){$f=$native->command($f['execution_id'],pr_command($f,'logic',array('QE_R_SOURCE'=>'yes')),true);pr_assert($f['page']===3);pr_assert(in_array('QE_A',$f['logical_skipped_ids'],true));pr_assert(in_array('QE_GROUP_B',$f['logical_excluded_ids'],true));$dto=EIPSI\AssessmentEditor\Runtime\EffectiveAssessmentProjection::frame($f);pr_assert(count(array_filter($dto['definition']['elements'],static function($e){return $e['type']!=='page_break';}))===1);},true);});

pr_test('Discarding a completed response resets conditional branches without changing the completed Study opportunity',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'yes');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a));$f=$native->command($f['execution_id'],pr_command($f,'next',$a));$a['QE_R_A']='first';$f=$native->command($f['execution_id'],pr_command($f,'next',$a));$a['QE_R_COMMON']='shared';$f=$native->command($f['execution_id'],pr_command($f,'submit',$a));$f=$native->command($f['execution_id'],pr_command($f,'discard'));pr_assert($f['state']==='ACTIVE'&&$f['session']===null);pr_assert($f['available_pages']===array(0,3));$f=$native->command($f['execution_id'],pr_command($f,'open'));$a=array('QE_R_SOURCE'=>'no');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a));pr_assert($f['available_pages']===array(0,2,3));pr_assert($f['session']['answers']===$a);},false,true);});
pr_test('Expired questionnaire session resets conditional branches before receiving another answer',function(){pr_exclusion_test(function($native,$f){$a=array('QE_R_SOURCE'=>'yes');$f=$native->command($f['execution_id'],pr_command($f,'logic',$a));$future=new Owner($native->store,static function(){return time()+120;});$f=$future->view($f['execution_id']);pr_assert($f['session_reset']&&$f['session']===null);pr_assert($f['available_pages']===array(0,3));$f=$future->command($f['execution_id'],pr_command($f,'open'));pr_assert($f['session']['answers']===array());});});
pr_test('Longitudinal simulation repeats with pending branches and keeps the previous completed attempt',function(){pr_exclusion_test(function($native,$f,$cookie,$protocol,$d,$assessment){
 $screen=EIPSI\StudyEngine\Longitudinal\InitialScreen::defaults();$screen['authentication']['verification']='NEVER';$screen['authentication']['confirm_after_first']=false;$protocol=EIPSI\StudyEngine\Longitudinal\Configuration::apply($protocol,array('initial_screen'=>$screen,'email_enabled'=>false));foreach($protocol['nodes'] as &$n)if($n['id']===$assessment){$n['metadata']['unique_response']=false;$n['schedule']['window']=array('kind'=>'DURATION','duration'=>array('kind'=>'ELAPSED','seconds'=>7200));}unset($n);$ctx=array('created_at'=>'2026-10-13T08:00:00Z','timezone'=>'UTC','seed_hex'=>str_repeat('01',32));$a=array('QE_R_SOURCE'=>'yes');$commands=array(array('kind'=>'ENTER','data'=>array('email'=>'repeat@example.test')),array('kind'=>'ANSWER','data'=>array('answers'=>$a,'touched'=>array())),array('kind'=>'NEXT','data'=>array('answers'=>$a,'touched'=>array())));$a['QE_R_A']='first';$commands[]=array('kind'=>'NEXT','data'=>array('answers'=>$a,'touched'=>array()));$a['QE_R_COMMON']='shared';$commands[]=array('kind'=>'SUBMIT','data'=>array('answers'=>$a,'touched'=>array()));$run=function()use($protocol,$ctx,&$commands,$d,$assessment){return EIPSI\StudyEngine\Builder\Experience::run($protocol,$ctx,$commands,array($assessment=>$d));};$before=$run();pr_assert($before['completion_can_repeat']);$commands[]=array('kind'=>'REPEAT','data'=>array());$r=$run();pr_assert($r['assessment']['available_pages']===array(0,3));pr_assert($r['assessment']['session']['answers']===array());$commands[]=array('kind'=>'ANSWER','data'=>array('answers'=>array('QE_R_SOURCE'=>'no'),'touched'=>array()));$r=$run();pr_assert($r['assessment']['available_pages']===array(0,2,3));pr_assert($r['snapshot']['logical_trajectory']['answers']===$before['snapshot']['logical_trajectory']['answers']);
});});
